"use client";

import type { UTCTimestamp } from "lightweight-charts";

export type DrawingTool =
  | "cursor"
  | "trend"
  | "horizontal"
  | "vertical"
  | "rectangle"
  | "fib"
  | "brush"
  | "eraser";

export interface DrawingAnchor {
  time: UTCTimestamp;
  price: number;
}

export interface TrendDrawing {
  id: number;
  kind: "trend";
  p1: DrawingAnchor;
  p2: DrawingAnchor;
  color: string;
}

export interface HorizontalDrawing {
  id: number;
  kind: "horizontal";
  price: number;
  color: string;
}

export interface VerticalDrawing {
  id: number;
  kind: "vertical";
  time: UTCTimestamp;
  color: string;
}

export interface RectangleDrawing {
  id: number;
  kind: "rectangle";
  p1: DrawingAnchor;
  p2: DrawingAnchor;
  color: string;
}

export interface FibDrawing {
  id: number;
  kind: "fib";
  p1: DrawingAnchor;
  p2: DrawingAnchor;
  color: string;
}

export interface BrushDrawing {
  id: number;
  kind: "brush";
  points: DrawingAnchor[];
  color: string;
}

export type Drawing =
  | TrendDrawing
  | HorizontalDrawing
  | VerticalDrawing
  | RectangleDrawing
  | FibDrawing
  | BrushDrawing;

export const DRAW_COLOR = "#38bdf8";

export const FIB_LEVELS = [0, 0.236, 0.382, 0.5, 0.618, 0.786, 1];

export function fibPrice(
  p1: DrawingAnchor,
  p2: DrawingAnchor,
  level: number,
): number {
  return p1.price + (p2.price - p1.price) * level;
}

/** Shortest distance from point (px, py) to segment a→b, in the same units. */
export function distToSegment(
  px: number,
  py: number,
  ax: number,
  ay: number,
  bx: number,
  by: number,
): number {
  const dx = bx - ax;
  const dy = by - ay;
  const lenSq = dx * dx + dy * dy;
  if (lenSq === 0) return Math.hypot(px - ax, py - ay);
  const t = Math.min(1, Math.max(0, ((px - ax) * dx + (py - ay) * dy) / lenSq));
  return Math.hypot(px - (ax + t * dx), py - (ay + t * dy));
}

export interface PixelConverters {
  toX: (time: UTCTimestamp) => number | null;
  toY: (price: number) => number | null;
}

/**
 * Hit-test a drawing against a media-space point. Used by the eraser tool
 * (click a drawing to delete it). Returns true when the point is on the
 * drawing within `tolerance` pixels.
 */
export function hitTestDrawing(
  drawing: Drawing,
  x: number,
  y: number,
  converters: PixelConverters,
  tolerance = 6,
): boolean {
  const { toX, toY } = converters;
  switch (drawing.kind) {
    case "trend": {
      const x1 = toX(drawing.p1.time);
      const y1 = toY(drawing.p1.price);
      const x2 = toX(drawing.p2.time);
      const y2 = toY(drawing.p2.price);
      if (x1 == null || y1 == null || x2 == null || y2 == null) return false;
      return distToSegment(x, y, x1, y1, x2, y2) <= tolerance;
    }
    case "horizontal": {
      const ly = toY(drawing.price);
      if (ly == null) return false;
      return Math.abs(y - ly) <= tolerance;
    }
    case "vertical": {
      const lx = toX(drawing.time);
      if (lx == null) return false;
      return Math.abs(x - lx) <= tolerance;
    }
    case "rectangle": {
      const x1 = toX(drawing.p1.time);
      const y1 = toY(drawing.p1.price);
      const x2 = toX(drawing.p2.time);
      const y2 = toY(drawing.p2.price);
      if (x1 == null || y1 == null || x2 == null || y2 == null) return false;
      return (
        x >= Math.min(x1, x2) - tolerance &&
        x <= Math.max(x1, x2) + tolerance &&
        y >= Math.min(y1, y2) - tolerance &&
        y <= Math.max(y1, y2) + tolerance
      );
    }
    case "fib": {
      const x1 = toX(drawing.p1.time);
      const x2 = toX(drawing.p2.time);
      if (x1 == null || x2 == null) return false;
      // Levels render from the left anchor edge extending right.
      if (x < Math.min(x1, x2) - tolerance) return false;
      return FIB_LEVELS.some((level) => {
        const ly = toY(fibPrice(drawing.p1, drawing.p2, level));
        return ly != null && Math.abs(y - ly) <= tolerance;
      });
    }
    case "brush": {
      const pts = drawing.points;
      for (let i = 1; i < pts.length; i++) {
        const prev = pts[i - 1];
        const curr = pts[i];
        const x1 = toX(prev.time);
        const y1 = toY(prev.price);
        const x2 = toX(curr.time);
        const y2 = toY(curr.price);
        if (x1 == null || y1 == null || x2 == null || y2 == null) continue;
        if (distToSegment(x, y, x1, y1, x2, y2) <= tolerance) return true;
      }
      return false;
    }
  }
}

"use client";

import type {
  IChartApiBase,
  IPrimitivePaneView,
  ISeriesApi,
  ISeriesPrimitive,
  SeriesAttachedParameter,
  SeriesType,
  Time,
  UTCTimestamp,
} from "lightweight-charts";
import {
  FIB_LEVELS,
  fibPrice,
  type Drawing,
  type DrawingAnchor,
} from "./drawings";

const priceFormatter = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 2,
});

/**
 * Series primitive that renders user drawings (trend lines, horizontal /
 * vertical lines, rectangles, fib retracements, freehand brush strokes) on
 * top of the candles series, plus a dashed in-progress preview.
 */
export class DrawingsPrimitive implements ISeriesPrimitive<Time> {
  private chart: IChartApiBase<Time> | null = null;
  private series: ISeriesApi<SeriesType, Time> | null = null;
  private requestUpdateFn: (() => void) | null = null;
  private drawings: Drawing[] = [];
  private preview: Drawing | null = null;

  attached(param: SeriesAttachedParameter<Time, SeriesType>): void {
    this.chart = param.chart;
    this.series = param.series;
    this.requestUpdateFn = param.requestUpdate;
  }

  detached(): void {
    this.chart = null;
    this.series = null;
    this.requestUpdateFn = null;
  }

  setDrawings(drawings: Drawing[]): void {
    this.drawings = drawings;
    this.requestUpdateFn?.();
  }

  setPreview(preview: Drawing | null): void {
    this.preview = preview;
    this.requestUpdateFn?.();
  }

  paneViews(): readonly IPrimitivePaneView[] {
    return [
      {
        zOrder: () => "top",
        renderer: () => ({
          // `target` and `scope` are contextually typed by the interfaces
          // above; the concrete canvas-target type is intentionally not
          // imported because the package does not export it.
          draw: (target) => {
            const chart = this.chart;
            const series = this.series;
            if (!chart || !series) return;
            const all = this.preview
              ? [...this.drawings, this.preview]
              : this.drawings;
            if (all.length === 0) return;

            target.useBitmapCoordinateSpace((scope) => {
              const {
                context: ctx,
                horizontalPixelRatio,
                verticalPixelRatio,
                bitmapSize,
              } = scope;
              const ratio = (horizontalPixelRatio + verticalPixelRatio) / 2;
              const toX = (time: UTCTimestamp): number | null => {
                const c = chart.timeScale().timeToCoordinate(time);
                return c == null ? null : c * horizontalPixelRatio;
              };
              const toY = (price: number): number | null => {
                const c = series.priceToCoordinate(price);
                return c == null ? null : c * verticalPixelRatio;
              };
              all.forEach((drawing, index) => {
                const isPreview =
                  this.preview != null && index === all.length - 1;
                this.drawOne(
                  ctx,
                  drawing,
                  toX,
                  toY,
                  bitmapSize.width,
                  bitmapSize.height,
                  ratio,
                  isPreview,
                );
              });
            });
          },
        }),
      },
    ];
  }

  private drawOne(
    ctx: CanvasRenderingContext2D,
    drawing: Drawing,
    toX: (time: UTCTimestamp) => number | null,
    toY: (price: number) => number | null,
    width: number,
    height: number,
    ratio: number,
    isPreview: boolean,
  ): void {
    ctx.save();
    if (isPreview) {
      ctx.globalAlpha = 0.85;
      ctx.setLineDash([6 * ratio, 5 * ratio]);
    }
    switch (drawing.kind) {
      case "trend":
        this.drawTrend(
          ctx,
          toX,
          toY,
          drawing.p1,
          drawing.p2,
          drawing.color,
          ratio,
        );
        break;
      case "horizontal": {
        const y = toY(drawing.price);
        if (y != null) {
          this.strokeLine(
            ctx,
            0,
            y,
            width,
            y,
            drawing.color,
            Math.max(1, 1.5 * ratio),
          );
        }
        break;
      }
      case "vertical": {
        const x = toX(drawing.time);
        if (x != null) {
          this.strokeLine(
            ctx,
            x,
            0,
            x,
            height,
            drawing.color,
            Math.max(1, 1.5 * ratio),
          );
        }
        break;
      }
      case "rectangle":
        this.drawRectangle(
          ctx,
          toX,
          toY,
          drawing.p1,
          drawing.p2,
          drawing.color,
          ratio,
        );
        break;
      case "fib":
        this.drawFib(
          ctx,
          toX,
          toY,
          width,
          drawing.p1,
          drawing.p2,
          drawing.color,
          ratio,
        );
        break;
      case "brush":
        this.drawBrush(ctx, toX, toY, drawing.points, drawing.color, ratio);
        break;
    }
    ctx.restore();
  }

  private strokeLine(
    ctx: CanvasRenderingContext2D,
    x1: number,
    y1: number,
    x2: number,
    y2: number,
    color: string,
    lineWidth: number,
  ): void {
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
  }

  private drawTrend(
    ctx: CanvasRenderingContext2D,
    toX: (time: UTCTimestamp) => number | null,
    toY: (price: number) => number | null,
    p1: DrawingAnchor,
    p2: DrawingAnchor,
    color: string,
    ratio: number,
  ): void {
    const x1 = toX(p1.time);
    const y1 = toY(p1.price);
    const x2 = toX(p2.time);
    const y2 = toY(p2.price);
    if (x1 == null || y1 == null || x2 == null || y2 == null) return;
    this.strokeLine(ctx, x1, y1, x2, y2, color, Math.max(1.5, 2 * ratio));
    ctx.fillStyle = color;
    for (const [x, y] of [
      [x1, y1],
      [x2, y2],
    ] as const) {
      ctx.beginPath();
      ctx.arc(x, y, 3 * ratio, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  private drawRectangle(
    ctx: CanvasRenderingContext2D,
    toX: (time: UTCTimestamp) => number | null,
    toY: (price: number) => number | null,
    p1: DrawingAnchor,
    p2: DrawingAnchor,
    color: string,
    ratio: number,
  ): void {
    const x1 = toX(p1.time);
    const y1 = toY(p1.price);
    const x2 = toX(p2.time);
    const y2 = toY(p2.price);
    if (x1 == null || y1 == null || x2 == null || y2 == null) return;
    const x = Math.min(x1, x2);
    const y = Math.min(y1, y2);
    const w = Math.abs(x2 - x1);
    const h = Math.abs(y2 - y1);
    ctx.save();
    ctx.globalAlpha *= 0.12;
    ctx.fillStyle = color;
    ctx.fillRect(x, y, w, h);
    ctx.restore();
    ctx.strokeStyle = color;
    ctx.lineWidth = Math.max(1, 1.5 * ratio);
    ctx.strokeRect(x, y, w, h);
  }

  private drawFib(
    ctx: CanvasRenderingContext2D,
    toX: (time: UTCTimestamp) => number | null,
    toY: (price: number) => number | null,
    width: number,
    p1: DrawingAnchor,
    p2: DrawingAnchor,
    color: string,
    ratio: number,
  ): void {
    const x1 = toX(p1.time);
    const x2 = toX(p2.time);
    if (x1 == null || x2 == null) return;
    const startX = Math.min(x1, x2);
    // Faint diagonal connecting the two anchors.
    const y1 = toY(p1.price);
    const y2 = toY(p2.price);
    if (y1 != null && y2 != null) {
      ctx.save();
      ctx.globalAlpha *= 0.5;
      ctx.setLineDash([4 * ratio, 4 * ratio]);
      this.strokeLine(ctx, x1, y1, x2, y2, color, Math.max(1, ratio));
      ctx.restore();
    }
    ctx.font = `${11 * ratio}px ui-monospace, SFMono-Regular, monospace`;
    ctx.textAlign = "right";
    ctx.textBaseline = "bottom";
    for (const level of FIB_LEVELS) {
      const price = fibPrice(p1, p2, level);
      const y = toY(price);
      if (y == null) continue;
      this.strokeLine(ctx, startX, y, width, y, color, Math.max(1, ratio));
      ctx.fillStyle = color;
      ctx.fillText(
        `${(level * 100).toFixed(1)}% · ${priceFormatter.format(price)}`,
        width - 6 * ratio,
        y - 3 * ratio,
      );
    }
  }

  private drawBrush(
    ctx: CanvasRenderingContext2D,
    toX: (time: UTCTimestamp) => number | null,
    toY: (price: number) => number | null,
    points: DrawingAnchor[],
    color: string,
    ratio: number,
  ): void {
    ctx.strokeStyle = color;
    ctx.lineWidth = Math.max(1.5, 2 * ratio);
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.beginPath();
    let penDown = false;
    for (const point of points) {
      const x = toX(point.time);
      const y = toY(point.price);
      if (x == null || y == null) {
        penDown = false;
        continue;
      }
      if (!penDown) {
        ctx.moveTo(x, y);
        penDown = true;
      } else {
        ctx.lineTo(x, y);
      }
    }
    ctx.stroke();
  }
}

"use client";

import type {
  CandlestickData,
  HistogramData,
  LineData,
  UTCTimestamp,
} from "lightweight-charts";

export interface Timeframe {
  id: string;
  label: string;
  seconds: number;
}

export const TIMEFRAMES: Timeframe[] = [
  { id: "1m", label: "1m", seconds: 60 },
  { id: "5m", label: "5m", seconds: 300 },
  { id: "15m", label: "15m", seconds: 900 },
  { id: "1H", label: "1H", seconds: 3600 },
  { id: "4H", label: "4H", seconds: 14400 },
  { id: "1D", label: "1D", seconds: 86400 },
];

export const CANDLE_COUNT = 140;
export const MA_FAST_PERIOD = 9;
export const MA_SLOW_PERIOD = 21;

export const UP_COLOR = "#26a69a";
export const DOWN_COLOR = "#ef5350";

export interface OhlcvDataset {
  timeframe: Timeframe;
  candles: CandlestickData<UTCTimestamp>[];
  volumes: HistogramData<UTCTimestamp>[];
  maFast: LineData<UTCTimestamp>[];
  maSlow: LineData<UTCTimestamp>[];
}

function hashSeed(text: string): number {
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function mulberry32(seed: number): () => number {
  let state = seed;
  return () => {
    state |= 0;
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Single-pass moving average with a running sum — O(n), no per-point
 * slice/reduce allocations. Matches the naive windowed definition exactly,
 * including the warm-up prefix (averages over fewer than `period` points).
 */
function movingAverage(
  closes: number[],
  times: UTCTimestamp[],
  period: number,
): LineData<UTCTimestamp>[] {
  const result: LineData<UTCTimestamp>[] = new Array(closes.length);
  let sum = 0;
  for (let index = 0; index < closes.length; index += 1) {
    sum += closes[index];
    if (index >= period) sum -= closes[index - period];
    result[index] = {
      time: times[index],
      value: sum / Math.min(index + 1, period),
    };
  }
  return result;
}

export function volumeBarColor(up: boolean): string {
  return up ? "rgba(38, 166, 154, 0.5)" : "rgba(239, 83, 80, 0.5)";
}

/** Assemble a dataset from candle + volume arrays (computes both MAs). */
export function buildDataset(
  timeframe: Timeframe,
  candles: CandlestickData<UTCTimestamp>[],
  volumes: HistogramData<UTCTimestamp>[],
): OhlcvDataset {
  const closes = candles.map((candle) => candle.close);
  const times = candles.map((candle) => candle.time);
  return {
    timeframe,
    candles,
    volumes,
    maFast: movingAverage(closes, times, MA_FAST_PERIOD),
    maSlow: movingAverage(closes, times, MA_SLOW_PERIOD),
  };
}

/**
 * Insert or replace the last candle of a mutable cache by time. Used to keep
 * a local candle list in step with streaming updates (same time replaces,
 * newer time appends). Out-of-order older ticks are ignored.
 */
export function upsertCandle(
  candles: CandlestickData<UTCTimestamp>[],
  candle: CandlestickData<UTCTimestamp>,
): void {
  const last = candles[candles.length - 1];
  if (!last || candle.time > last.time) {
    candles.push(candle);
    return;
  }
  if (candle.time === last.time) {
    candles[candles.length - 1] = candle;
  }
}

/** Average of up to the last `period` closes (fewer while warming up). */
export function movingTailAverage(closes: number[], period: number): number {
  const window = closes.slice(Math.max(0, closes.length - period));
  if (window.length === 0) return 0;
  return window.reduce((total, close) => total + close, 0) / window.length;
}

/**
 * Deterministic dummy OHLCV series: same (timeframe, anchor) always yields
 * the same candles (seeded PRNG + floored end time), so switching timeframes
 * back and forth is stable and unit-testable. Prices random-walk around a
 * BTC-like base with volume correlated to candle range.
 *
 * Pass an explicit `now` (ms) wherever repeatability matters — the default
 * `Date.now()` means two calls straddling a timeframe boundary return
 * different datasets. For UI call sites prefer `stableDummyDataset`, which
 * pins one anchor per timeframe for the whole session.
 */
export function generateOhlcv(
  timeframeId: string,
  now: number = Date.now(),
): OhlcvDataset {
  const timeframe =
    TIMEFRAMES.find((entry) => entry.id === timeframeId) ?? TIMEFRAMES[3];
  const random = mulberry32(hashSeed(`kick-ui-ohlcv-${timeframe.id}`));

  const endTime =
    Math.floor(now / 1000 / timeframe.seconds) * timeframe.seconds;
  const startTime = endTime - (CANDLE_COUNT - 1) * timeframe.seconds;

  const candles: CandlestickData<UTCTimestamp>[] = [];
  const volumes: HistogramData<UTCTimestamp>[] = [];

  let price = 67400 * (0.94 + random() * 0.12);
  const baseVolume = 42 + random() * 30;

  for (let index = 0; index < CANDLE_COUNT; index += 1) {
    const time = (startTime + index * timeframe.seconds) as UTCTimestamp;
    const volatility = price * 0.004 * Math.sqrt(timeframe.seconds / 60);
    const open = price;
    const change = (random() - 0.5) * volatility * 2;
    const close = Math.max(1, open + change);
    const high = Math.max(open, close) + random() * volatility * 0.6;
    const low = Math.max(
      1,
      Math.min(open, close) - random() * volatility * 0.6,
    );
    const up = close >= open;
    const volume =
      baseVolume *
      (0.4 + random() * 1.6) *
      (1 + (Math.abs(change) / volatility) * 0.8);

    candles.push({ time, open, high, low, close });
    volumes.push({
      time,
      value: Math.round(volume * 100) / 100,
      color: volumeBarColor(up),
    });
    price = close;
  }

  return buildDataset(timeframe, candles, volumes);
}

// Session-pinned anchors: at most one per known timeframe id.
const dummyAnchorCache = new Map<string, number>();

/**
 * Dummy dataset with a stable anchor per timeframe for the whole session.
 * Repeated calls (and timeframe switches) within one session always return
 * the same candles — the boundary-crossing flakiness of raw `Date.now()`
 * cannot occur. UI code should call this; tests should call `generateOhlcv`
 * with an explicit anchor.
 */
export function stableDummyDataset(timeframeId: string): OhlcvDataset {
  let anchor = dummyAnchorCache.get(timeframeId);
  if (anchor === undefined) {
    anchor = Date.now();
    dummyAnchorCache.set(timeframeId, anchor);
  }
  return generateOhlcv(timeframeId, anchor);
}

const priceFormatter = new Intl.NumberFormat("en-US", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

export function formatPrice(value: number): string {
  return priceFormatter.format(value);
}

export function formatCompactVolume(value: number): string {
  if (value >= 1_000_000) return `${(value / 1_000_000).toFixed(2)}M`;
  if (value >= 1_000) return `${(value / 1_000).toFixed(2)}K`;
  return value.toFixed(2);
}

"use client";

import type {
  CandlestickData,
  HistogramData,
  UTCTimestamp,
} from "lightweight-charts";
import {
  CANDLE_COUNT,
  TIMEFRAMES,
  buildDataset,
  volumeBarColor,
  type OhlcvDataset,
} from "./market-data";

export const FEED_SYMBOL = "BTCUSDT";
const REST_BASE = "https://data-api.binance.vision";
const WS_BASE = "wss://data-stream.binance.vision";

const INTERVALS: Record<string, string> = {
  "1m": "1m",
  "5m": "5m",
  "15m": "15m",
  "1H": "1h",
  "4H": "4h",
  "1D": "1d",
};

export function intervalFor(timeframeId: string): string | null {
  return INTERVALS[timeframeId] ?? null;
}

export function klineStreamUrl(timeframeId: string): string | null {
  const interval = intervalFor(timeframeId);
  if (!interval) return null;
  return `${WS_BASE}/ws/${FEED_SYMBOL.toLowerCase()}@kline_${interval}`;
}

export interface KlineTick {
  candle: CandlestickData<UTCTimestamp>;
  volume: HistogramData<UTCTimestamp>;
  isClosed: boolean;
}

function toFiniteNumber(value: unknown): number | null {
  if (typeof value === "string" && value.trim() === "") return null;
  const parsed = typeof value === "string" ? Number(value) : value;
  return typeof parsed === "number" && Number.isFinite(parsed) ? parsed : null;
}

/**
 * Parse a `kline` websocket event into a chart tick. Returns null for
 * anything unexpected so a malformed message can never corrupt the series.
 */
export function parseKlineTick(message: unknown): KlineTick | null {
  if (typeof message !== "object" || message === null) return null;
  const event = (message as { e?: unknown }).e;
  const raw = (message as { k?: unknown }).k;
  if (event !== "kline" || typeof raw !== "object" || raw === null) return null;
  const k = raw as Record<string, unknown>;

  const openTime = toFiniteNumber(k.t);
  const open = toFiniteNumber(k.o);
  const high = toFiniteNumber(k.h);
  const low = toFiniteNumber(k.l);
  const close = toFiniteNumber(k.c);
  const volume = toFiniteNumber(k.v);
  if (
    openTime == null ||
    open == null ||
    high == null ||
    low == null ||
    close == null ||
    volume == null
  ) {
    return null;
  }

  const time = Math.floor(openTime / 1000) as UTCTimestamp;
  const up = close >= open;
  return {
    candle: { time, open, high, low, close },
    volume: { time, value: volume, color: volumeBarColor(up) },
    isClosed: k.x === true,
  };
}

type KlineRow = [number, string, string, string, string, string, ...unknown[]];

function parseKlineRow(row: unknown): {
  candle: CandlestickData<UTCTimestamp>;
  volume: HistogramData<UTCTimestamp>;
} | null {
  if (!Array.isArray(row) || row.length < 7) return null;
  const [openTime, openRaw, highRaw, lowRaw, closeRaw, volumeRaw] =
    row as KlineRow;
  const open = toFiniteNumber(openRaw);
  const high = toFiniteNumber(highRaw);
  const low = toFiniteNumber(lowRaw);
  const close = toFiniteNumber(closeRaw);
  const volume = toFiniteNumber(volumeRaw);
  if (
    typeof openTime !== "number" ||
    !Number.isFinite(openTime) ||
    open == null ||
    high == null ||
    low == null ||
    close == null ||
    volume == null
  ) {
    return null;
  }
  const time = Math.floor(openTime / 1000) as UTCTimestamp;
  const up = close >= open;
  return {
    candle: { time, open, high, low, close },
    volume: { time, value: volume, color: volumeBarColor(up) },
  };
}

/** Map raw `/klines` rows to a dataset. Pure — unit-tested, no network. */
export function mapKlinesToDataset(
  timeframeId: string,
  rows: unknown,
): OhlcvDataset {
  const timeframe =
    TIMEFRAMES.find((entry) => entry.id === timeframeId) ?? TIMEFRAMES[3];
  if (!Array.isArray(rows) || rows.length === 0) {
    throw new Error("Empty kline response");
  }
  const candles: CandlestickData<UTCTimestamp>[] = [];
  const volumes: HistogramData<UTCTimestamp>[] = [];
  for (const row of rows) {
    const parsed = parseKlineRow(row);
    if (!parsed) throw new Error("Malformed kline row");
    candles.push(parsed.candle);
    volumes.push(parsed.volume);
  }
  return buildDataset(timeframe, candles, volumes);
}

/**
 * Fetch recent klines for a timeframe. Throws on any failure so callers can
 * fall back to the local simulator.
 */
export async function fetchHistory(
  timeframeId: string,
  signal: AbortSignal,
): Promise<OhlcvDataset> {
  const interval = intervalFor(timeframeId);
  if (!interval) throw new Error(`Unsupported timeframe: ${timeframeId}`);
  const response = await fetch(
    `${REST_BASE}/api/v3/klines?symbol=${FEED_SYMBOL}&interval=${interval}&limit=${CANDLE_COUNT}`,
    { signal },
  );
  if (!response.ok) {
    throw new Error(`Klines request failed: ${response.status}`);
  }
  return mapKlinesToDataset(timeframeId, await response.json());
}

export interface KlineSubscription {
  onTick: (tick: KlineTick) => void;
  onDisconnect: () => void;
}

/**
 * Open a kline websocket for a timeframe. Returns an unsubscribe function.
 * Reconnection policy is left to the caller.
 */
export function subscribeKlines(
  timeframeId: string,
  subscription: KlineSubscription,
): () => void {
  const url = klineStreamUrl(timeframeId);
  if (!url) throw new Error(`Unsupported timeframe: ${timeframeId}`);
  const socket = new WebSocket(url);
  let closed = false;

  socket.onmessage = (event: MessageEvent) => {
    try {
      const tick = parseKlineTick(JSON.parse(event.data));
      if (tick) subscription.onTick(tick);
    } catch {
      // Ignore malformed frames; the next tick repairs nothing to repair.
    }
  };
  socket.onclose = () => {
    if (!closed) subscription.onDisconnect();
  };
  socket.onerror = () => {
    // onclose follows error; report disconnect once via the close path.
    try {
      socket.close();
    } catch {
      // Already closing — nothing to do.
    }
  };

  return () => {
    closed = true;
    try {
      socket.close();
    } catch {
      // Already closed — nothing to do.
    }
  };
}
